import {places,recipients,deliveries} from './post-office-content.mjs';
import {startPostOffice,resumePostOffice,setPostCourier,clauseText,appendPostClause,editPostClause,setPostComposer,setPostPackingInput,submitPostPacking,packPostTogether,restartPostRoute,stepPostRoute,setPostPrediction,setPostReading,setPostSupport,stepPostHelp} from './post-office-core.mjs';
import {guideRail} from './garden-ui.mjs';
import {avatars,portrait} from './companions.mjs';
import {hearButton} from './play-media.mjs';
import {learningInvitations} from './learning-invitations.mjs';

const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const current=s=>s.postOffice?.visits?.find(v=>v.id===s.postOffice.current)||null;
const place=id=>places.find(p=>p.id===id);
const person=id=>recipients.find(p=>p.id===id);
const btn=(attr,text,kind='secondary',disabled=false)=>`<button type="button" class="${kind}" ${attr}${disabled?' disabled':''}>${text}</button>`;
const placeMark={post:'✉',cafe:'♧',orchard:'❧',hill:'✦'};
const welcome='The storm scattered the post. Our neighbors are waiting for parcels, and your broom is ready. Read an order, pack what is needed, and write a flight plan. We will fly one instruction at a time. You can change your plan, get help, or take a break.';
function courier(state,style,carrying=true){
 const avatar=avatars.find(a=>a.id===state.garden?.avatar)||avatars[0];
 const face=portrait(avatar.id,true).replace('<svg ','<svg width="116" height="136" style="width:116px;height:136px" ');
 return `<g class="post-courier" data-courier-avatar="${avatar.id}"><path d="M-40 26H39" stroke="#866544" stroke-width="5" stroke-linecap="round"/><path d="M-31 20l-27-8 9 15-9 13 27-9Z" fill="#d9b96e" stroke="#866544" stroke-width="1.5"/><path d="M-11 10l15 14h14" fill="none" stroke="#183f39" stroke-width="5" stroke-linecap="round"/><g transform="translate(-25,-47) scale(.43)">${face}</g>${style==='witch'?'<path d="M-27-32H22L1-63-9-35Z" fill="#655276" stroke="#433c50" stroke-width="1.5"/><path d="M-10-39H13" stroke="#e9b84a" stroke-width="4"/>':'<path d="M-22-33Q-3-52 17-33Z" fill="#abc4da" stroke="#183f39"/><path d="M-21-30H18" stroke="#183f39" stroke-width="3"/>'}<path d="M7 7l16 6" stroke="${avatar.skin}" stroke-width="5" stroke-linecap="round"/>${carrying?'<rect x="21" y="7" width="20" height="19" rx="2" fill="#d6b77d" stroke="#75593c"/><path d="M22 9l8 7 10-7" fill="none" stroke="#75593c"/>':''}</g>`;
}
function landmark(id,x,y){
 const art={
 post:'<path d="M-40 20V-24H39V20" fill="#f7dfb0"/><path d="M-48-24L0-53 48-24Z" fill="#655276"/><rect x="-9" y="-5" width="19" height="25" fill="#397958"/><rect x="-32" y="-16" width="15" height="13" fill="#abc4da"/><rect x="18" y="-16" width="15" height="13" fill="#abc4da"/><path d="M-26-49V-71Q-15-82-6-70V-49" fill="#397958"/><path d="M-26-66h20m-20 0 10 8 10-8" fill="none" stroke="#fffef9"/><path d="M-58 17v-40m0 0q-16-10-17 4m17-4q16-10 17 4" fill="none" stroke="#66926c" stroke-width="4"/>',
 cafe:'<path d="M-42 20V-28H43V20" fill="#fff4d6"/><path d="M-48-28l11-20H35L48-28Z" fill="#ce777d"/><path d="M-46-28h92M-29-44v16M-9-46v18M12-46v18M31-45v17" stroke="#fff4d6" stroke-width="7"/><path d="M-48-28h96" stroke="#183f39" stroke-width="2"/><rect x="-9" y="-4" width="20" height="24" fill="#397958"/><path d="M-32-9h14v12h-14zm49 0h14v12H17Z" fill="#abc4da"/><path d="M27-64q-13 10-10 15 9 5 17-3-11 1-7-12" fill="#e9b84a"/>',
 orchard:'<path d="M-45 19V-15M0 19V-36M44 19V-13" stroke="#866544" stroke-width="7"/><path d="M-70-12Q-72-46-47-48Q-18-49-21-12Z M-29-31Q-35-68 0-71Q35-69 30-31Z M21-10Q16-45 43-47Q73-46 69-10Z" fill="#7ca778"/><g fill="#e9b84a"><circle cx="-48" cy="-30" r="6"/><circle cx="3" cy="-49" r="6"/><circle cx="45" cy="-28" r="6"/></g>',
 hill:'<path d="M-75 20Q-20-57 0-27Q34-57 75 20Z" fill="#b4cda6"/><path d="M-10 15V-54H18" stroke="#866544" stroke-width="5" fill="none"/><path d="M5-53h28l-5 28H10Z" fill="#e9b84a" stroke="#866544"/><path d="M14-29l6-15 6 15" fill="#fffef9" stroke="none"/><path d="M-49-23l3-7 3 7 7 3-7 3-3 7-3-7-7-3Z" fill="#e9b84a"/>'
 };
 return `<g transform="translate(${x},${y})" stroke="#183f39" stroke-width="1.5" stroke-linejoin="round">${art[id]||''}</g>`;
}
export function postMap(state,visit,helper=false){
 const order=visit?.order,style=state.postOffice?.courier||'witch',location=helper?(visit.helperStep>0?order.helper.destination:'post'):visit?.playback?.location||'post',here=place(location)||places[0];
 const destination=helper?order?.helper.destination:order?.destination;
 const carrying=helper?visit.helperStep<2:visit?.playback?.status!=='delivered';
 const links=places.flatMap((a,i)=>places.slice(i+1).map(b=>`<path d="M${a.x} ${a.y+15}L${b.x} ${b.y+15}" fill="none" stroke="#88aaa5" stroke-width="2" stroke-dasharray="3 8"/>`)).join('');
 const alt=`${helper?'Separate example map. ':''}${style==='witch'?'Flying witch':'Sky rider'} at ${here.name}.${destination?` Parcel destination: ${place(destination)?.name}.`:''} ${carrying?'':' The parcel has been handed over.'} Dotted lines are possible flights, not required stops.`;
 return `<figure class="post-map ${helper?'post-help-map':''}"><svg viewBox="0 0 640 390" role="img" aria-label="${esc(alt)}"><path d="M9 95Q35-3 180 20Q310-20 440 20Q615 0 632 103L624 309Q604 390 430 365Q293 394 142 369Q-3 374 9 280Z" fill="#e2eee1"/><path d="M12 280Q230 230 326 293Q430 245 626 270V325Q543 390 326 366Q94 394 13 324Z" fill="#cddfbd"/><path d="M271 0Q303 60 270 120T310 238T293 388" stroke="#abcbd6" stroke-width="24" fill="none"/><path d="M256 143h58M261 151h58" stroke="#fffef9" stroke-width="2"/>${links}${places.map(p=>`${destination===p.id?`<ellipse cx="${p.x}" cy="${p.y+20}" rx="84" ry="32" fill="#f6e5ac" stroke="#9b7c36" stroke-dasharray="5 5"/>`:''}${landmark(p.id,p.x,p.y)}<text x="${p.x}" y="${p.y+52}" text-anchor="middle" fill="#183f39" font-size="16" font-family="Trebuchet MS,Verdana,sans-serif">${esc(p.name)}</text>`).join('')}<g transform="translate(${here.x},${here.y-31}) scale(.84)">${courier(state,style,carrying)}</g>${!carrying&&destination?`<g class="post-handoff" transform="translate(${place(destination).x+47},${place(destination).y+7})"><rect x="-12" y="-8" width="25" height="19" rx="2" fill="#fff4d6" stroke="#75593c"/><path d="M-12-7L0 2 13-7" fill="none" stroke="#75593c"/><circle cx="15" cy="-9" r="10" fill="#397958"/><path d="M10-9l4 4 7-8" stroke="#fffef9" stroke-width="2" fill="none"/></g>`:''}</svg><figcaption>${esc(alt)}</figcaption></figure>`;
}
function courierChoice(state){return `<div class="post-courier-choice" role="group" aria-label="Choose a courier appearance">${[['witch','Flying witch'],['rider','Sky rider']].map(([id,text])=>`<button type="button" class="method ${state.postOffice?.courier===id?'selected':''}" data-post-courier="${id}" aria-pressed="${state.postOffice?.courier===id}">${text}</button>`).join('')}<span class="tiny">Your explorer, your costume. Your guide stays with you.</span></div>`;}
function packingPicture(math){
 const groups=math.kind==='subtract'?[{label:'Set aside at the counter',count:math.b,reserved:true},{label:'Ready for the parcel',count:math.answer}]:math.pictures.groups;
 return `<div class="post-parcel-picture" role="img" aria-label="${esc(math.kind==='multiply'?`${math.a} equal bundles with ${math.b} ${math.unit} in each`:math.kind==='subtract'?`${math.a} ${math.unit}: ${math.b} set aside and the rest ready to pack`:`${math.a} ${math.unit} and ${math.b} more`)}">${groups.map(g=>`<div class="post-item-group ${g.reserved?'reserved':''}"><span>${esc(g.label)}</span><div>${Array.from({length:g.count},()=>`<span class="post-item" aria-hidden="true">${math.unit?.includes('star')?'✦':math.unit?.includes('ribbon')?'⌁':'▰'}</span>`).join('')}</div>${g.reserved?'<small>Not sent</small>':''}</div>`).join('')}</div>`;
}
function packing(v){
 const m=v.order.math,p=v.packing;
 return `<section class="post-packing" aria-labelledby="post-packing-title"><h2 id="post-packing-title">At the parcel counter</h2><p>${esc(m.prompt)}</p>${packingPicture(m)}${p.packed?`<p class="post-packed" id="post-packing-feedback" role="status">✉ Packed: ${m.answer} ${esc(m.unit)}.</p>${p.supported?`<p class="tiny">Packed together. ${esc(m.explanation)}</p>`:''}`:`<form id="post-packing-form" novalidate><label for="post-packing-input">How many go in the parcel?</label><div class="post-answer-line"><input id="post-packing-input" inputmode="numeric" autocomplete="off" type="text" value="${esc(p.input)}" aria-describedby="post-packing-feedback"><button class="primary" type="submit">Pack my parcel</button></div></form>${btn('data-post-pack-together','Pack together','secondary')}`}${!p.packed?`<p id="post-packing-feedback" role="status">${esc(p.error||p.feedback||'')}</p>`:''}<p class="tiny">You can draw, count, or pack with help.</p>${p.packed?btn('data-post-to-plan','Write my flight plan','primary'):''}</section>`;
}
function routeEditor(v){
 const c=v.composer||{place:'post',recipient:'clover'},full=v.clauses.length>=6;
 return `<section class="post-route" aria-labelledby="post-route-title"><h2 id="post-route-title">Write your flight plan</h2><p>Choose a stop. Add its words. Tell the courier who gets the parcel.</p><div class="post-word-bank"><div><label for="post-place">A place to fly</label><select id="post-place" data-post-composer="place">${places.map(p=>`<option value="${p.id}"${c.place===p.id?' selected':''}>${placeMark[p.id]} ${esc(p.name)}</option>`).join('')}</select><div class="post-bank-actions">${btn('data-post-add="go"',`Go to ${esc(place(c.place)?.name||'Willow Post Office')}`,'secondary',full)}${btn('data-post-add="then"',`Then go to ${esc(place(c.place)?.name||'Willow Post Office')}`,'secondary',full)}${btn('data-post-add="there"','Go there','secondary',full)}</div></div><div><label for="post-recipient">A person to receive it</label><select id="post-recipient" data-post-composer="recipient">${recipients.map(p=>`<option value="${p.id}"${c.recipient===p.id?' selected':''}>${esc(p.name)}</option>`).join('')}</select>${btn('data-post-add="give"',`Give the parcel to ${esc(person(c.recipient)?.name||'Clover')}`,'secondary',full)}</div></div><ol class="post-clauses" aria-label="Your flight instructions">${v.clauses.map((id,i)=>`<li class="${v.playback.active===i?'post-active-clause':''}"${v.playback.active===i?' aria-current="step"':''}><span>${esc(clauseText(id))}</span><div>${btn(`data-post-edit="up" data-post-index="${i}" aria-label="Move instruction ${i+1} up"`,'↑','secondary',i===0)}${btn(`data-post-edit="down" data-post-index="${i}" aria-label="Move instruction ${i+1} down"`,'↓','secondary',i===v.clauses.length-1)}${btn(`data-post-edit="remove" data-post-index="${i}" aria-label="Remove instruction ${i+1}"`,'Remove','text-button')}</div></li>`).join('')||'<li class="post-empty">Your words will wait here. Try a stop and a handoff.</li>'}</ol><p class="tiny">${v.clauses.length} of 6 instruction spaces used. Changing a line brings the courier back to the start; your packed parcel stays ready.</p>${v.clauses.length?hearButton(v.clauses.map(clauseText).join(' '),'Hear my flight plan'):''}<div>${v.packing.packed?btn('data-post-to-flight','Try my flight plan','primary'):btn('data-post-to-packing','Pack this parcel, then fly','secondary')}</div></section>`;
}
function helpView(state,v){
 if(!v.support.helper)return '';
 const h=v.order.helper,done=v.helperStep||0;
 return `<section class="post-example" aria-labelledby="post-example-title"><h3 id="post-example-title">Pip’s separate example</h3><p>Our real parcel and flight plan stay waiting. This is a different little delivery.</p>${postMap(state,v,true)}<ol><li${done===1?' class="post-active-clause"':''}>${esc(clauseText(h.clauses[0]))}</li><li${done===2?' class="post-active-clause"':''}>${esc(clauseText(h.clauses[1]))}</li></ol><p role="status">${done===0?'Example courier starts at Willow Post Office.':done===1?`Example courier reached ${esc(place(h.destination)?.name)}.`:`Example parcel reached ${esc(person(h.recipient)?.name)}.`}</p><div class="post-run-buttons">${btn('data-post-help-step="1"','Next example step','secondary',done>=2)}${btn('data-post-help-step="-1"','Previous example step','secondary',done<=0)}${btn('data-post-help-step="reset"','Start example again','text-button')}</div>${hearButton(h.clauses.map(clauseText).join(' '),'Hear Pip’s example')}<p class="tiny">This explanation is support. It does not count as completing your delivery.</p></section>`;
}
function investigation(state,v){
 if(v.closed)return `<section class="post-sheet"><h2>An earlier delivery is kept</h2><p>${esc(v.closedReason)}</p><a class="primary" href="#post/choose">Choose a fresh delivery</a><a class="secondary" href="#notes">Read the kept work</a></section>`;
 const o=v.order,p=v.playback;
 return `<section class="post-order" aria-labelledby="post-order-title"><div class="post-order-stamp" aria-hidden="true">${esc(person(o.recipient)?.emoji||'✉')}</div><div><h2 id="post-order-title">${esc(o.title)}</h2><p>${esc(o.request)}</p><p><strong>Start:</strong> ${esc(place(o.start)?.name)}. <strong>Deliver to:</strong> ${esc(person(o.recipient)?.name)} at ${esc(place(o.destination)?.name)}.</p>${hearButton(o.request,'Hear this order')}</div></section><nav class="post-step-links" aria-label="Delivery steps">${btn('data-post-to-packing','1. Pack','secondary')}${btn('data-post-to-plan','2. Plan','secondary')}${btn('data-post-to-flight','3. Fly','secondary')}</nav><div class="post-stage"><section class="post-flight" aria-labelledby="post-flight-title"><h2 id="post-flight-title">Your garden flight</h2>${postMap(state,v)}<p class="post-flight-status" role="status">${esc(p.feedback||(v.packing.packed?(v.clauses.length?'Parcel packed. Ready to fly your first instruction.':'Parcel packed. Write a flight plan when you are ready.'):`Ready at ${place(p.location)?.name}. Pack the parcel and write a route.`))}</p><div class="post-run-buttons">${!v.packing.packed?btn('data-post-to-packing','Pack the parcel first','primary'):p.status==='delivered'?btn('data-post-restart','Replay this flight','secondary'):['clarify','ended'].includes(p.status)?btn('data-post-edit-route','Change my flight plan','primary'):btn('data-post-step','Fly the next instruction','primary')}${p.status!=='delivered'?btn('data-post-restart','Back to the start','secondary'):''}</div>${v.completed&&p.status!=='delivered'?'<p class="tiny">This visit was delivered earlier. Replaying does not add another delivery.</p>':''}${p.status==='clarify'||p.status==='ended'?'<p>Keep your parcel. Change the words below, or return to the start to try them again.</p>':''}${p.log.length?`<details id="post-flight-log"><summary>Our flight log</summary><ol>${p.log.map(line=>`<li>${esc(line)}</li>`).join('')}</ol></details>`:''}<div class="post-locations"><h3>Where the neighbors are</h3>${places.map(t=>`<p><strong>${esc(t.name)}</strong>: ${recipients.filter(r=>v.recipientLocations[r.id]===t.id).map(r=>`${esc(r.emoji)} ${esc(r.name)}`).join(', ')||'the sorting counter'}</p>`).join('')}</div></section>${packing(v)}</div>${routeEditor(v)}<div class="post-optional"><details id="post-prediction"><summary>Where might this plan leave us?</summary><p>An optional idea, not a test. You can change your mind.</p><div class="post-prediction-choices">${places.map(t=>`<button type="button" class="method ${v.prediction===t.id?'selected':''}" data-post-prediction="${t.id}" aria-pressed="${v.prediction===t.id}">${esc(t.name)}</button>`).join('')}${btn('data-post-prediction="clear"','Leave it blank','text-button')}</div>${v.prediction?`<p class="tiny">${v.predictionAfterSupport?'This idea was selected after a flight or support.':'This idea was selected before a flight or support.'}</p>`:''}</details>${btn('data-post-help','Try Pip’s smaller example','secondary')}${helpView(state,v)}<details id="post-reading"><summary>How did we read this delivery?</summary><div class="post-prediction-choices">${[['unobserved','Reading not observed'],['together','Read together'],['independent','Reported read independently']].map(([id,text])=>`<button type="button" class="method ${v.reading===id?'selected':''}" data-post-reading="${id}" aria-pressed="${v.reading===id}">${text}</button>`).join('')}</div><p class="tiny">Narration and help stay in the record. This report does not measure decoding or fluency.</p></details><details><summary>A paper or talking idea</summary><p>Give someone directions to a pretend parcel. Ask them to follow exactly what you said. Which words would you change?</p><p class="tiny">Optional, unscored, and nothing to upload.</p></details></div>${p.status==='delivered'?`<section class="post-delivered" aria-label="A delivery completed"><span aria-hidden="true">✉ ✓</span><h2>A neighbor’s parcel has arrived.</h2><p>You can replay, try a new route, or choose another delivery. Help and another try are always welcome.</p>${btn('data-post-next','Choose the next delivery','primary')}<a class="secondary" href="#post/choose">See all six orders</a></section>`:''}`;
}
function catalog(){return `<section class="post-catalog"><h2>The sorting board</h2><p>Pick any order. Earlier parcels stay waiting while you explore another.</p><div>${deliveries.map(o=>`<article><span aria-hidden="true">${esc(person(o.recipient)?.emoji||'✉')}</span><h3>${esc(o.title)}</h3><p>${esc(person(o.recipient)?.name)} is at ${esc(place(o.destination)?.name)}.</p>${btn(`data-post-start="${o.id}"`,'Take this delivery','primary')}</article>`).join('')}</div></section>`;}
export function postOfficePage(state,slug){
 const v=current(state),xs=state.postOffice?.visits||[],hub=slug==='choose'||!v;
 return `<div class="post-office-page"><header class="page-heading"><a class="back" href="#home">← Pause in the garden</a><h1>Willow Post Office</h1><p>Parcels to pack. A broom to borrow. Neighbors to find.</p>${hearButton(welcome,'Hear our delivery story')}</header>${courierChoice(state)}${state.postOffice?.kept?'<p class="storage-warning" role="status">An earlier Post Office save could not be resumed. Its exact work is kept in <a href="#notes">Grown-up notes</a> and your download. New deliveries start separately.</p>':''}${hub?`<section class="post-welcome">${postMap(state,null)}<div><h2>The post must fly.</h2><p>The storm scattered our mail. Pip sorts the parcels. Dot checks the addresses. You can help the neighbors get what they need.</p><ol><li>Read an order and pack a parcel.</li><li>Build a flight plan with word cards.</li><li>Fly one instruction, then look and revise.</li></ol>${v?btn(`data-post-resume="${esc(v.id)}"`,'Continue the waiting delivery','primary'):''}</div></section>${catalog()}`:`<div class="post-game-layout"><div>${investigation(state,v)}</div>${guideRail(state,'{guide} says, “Our words have a job to do. Let’s try them, watch closely, and change anything that needs a clearer idea.”')}</div>`}${xs.length?`<details class="panel" id="post-saved-visits"><summary>Our delivery notebook (${xs.length} kept)</summary><p class="tiny">Latest 24 visits. Replaying the same visit does not add another completed delivery.</p>${[...xs].reverse().map(x=>`<p>${btn(`data-post-resume="${esc(x.id)}"`,`${esc(x.order?.title||x.id)} — ${x.closed?'kept earlier work':x.completed?'delivered before':'waiting'}`)}</p>`).join('')}</details>`:''}<p class="post-switch"><a class="secondary" href="#post/choose">Choose any order</a><a class="text-button" href="#home">Pause in the garden</a></p>${learningInvitations('post')}</div>`;
}
export function postOfficeNotes(state){
 const p=state.postOffice,xs=p?.visits||[];if(!p||!xs.length&&!p.kept)return '';
 return `<details class="panel"><summary>Willow Post Office (${xs.length} visits kept)</summary><p>Finite authored delivery practice: packing numbers, structured route composition, literal execution and revision. This does not establish independent decoding, free writing, programming proficiency or fact mastery. Up to 24 visits and 24 run checks per visit are retained. Support, reading reports and math attempts stay distinct.</p>${p.kept?`<h3>Earlier save kept exactly</h3><p>${esc(p.kept.reason)}</p><code class="post-kept-data">${esc(JSON.stringify(p.kept.payload))}</code>`:''}${xs.map(v=>`<section><h3>${esc(v.order?.title||v.id)}${v.closed?' — closed work':''}</h3>${v.closed?`<p>${esc(v.closedReason)}</p><code class="post-kept-data">${esc(JSON.stringify(v))}</code>`:`<p>${esc(v.order.request)}</p><p>Route: ${esc(v.clauses.map(clauseText).join(' ')||'not composed')}. Composition edits: ${v.revisions}. Completed once: ${v.completed?'yes':'no'}.</p><p>Packing attempts: ${esc(v.packing.attempts.map(a=>`${a.input} (${a.correct?'count fits':'another look'})`).join(', ')||'none')}. Packing support: ${v.packing.supported?'yes':'no'}. Current input: ${esc(v.packing.input)}. Parcel packed: ${v.packing.packed?'yes':'no'}.</p><p>Reading: ${esc(v.reading)}. Narration requested: ${v.support.audioRequested?'yes':'no'} (playback not verified). Separate example opened: ${v.support.helper?'yes':'no'}. Prediction: ${esc(v.prediction||'none')}${v.predictionAfterSupport?' (after execution or support)':''}.</p><p>Waiting at ${esc(place(v.playback.location)?.name)}; next instruction index ${v.playback.cursor}; ${esc(v.playback.status)}.</p><details><summary>Route checks (${v.checks.length})</summary><pre class="post-kept-data">${esc(JSON.stringify(v.checks,null,2))}</pre></details>`}</section>`).join('')}</details>`;
}
export function bindPostOffice(state,{save,render,navigate,focus}){
 const redraw=target=>{const open=[...document.querySelectorAll('.post-office-page details[id][open]')].map(d=>d.id);save();render();for(const id of open){const d=document.getElementById(id);if(d)d.open=true;}if(target)focus(target);};
 const bind=(selector,fn,target)=>document.querySelectorAll(selector).forEach(b=>b.addEventListener('click',()=>{fn(b);redraw(target);}));
 document.querySelectorAll('[data-post-start]').forEach(b=>b.addEventListener('click',()=>{startPostOffice(state,b.dataset.postStart);save();navigate('#post');focus('#post-order-title');}));
 document.querySelectorAll('[data-post-resume]').forEach(b=>b.addEventListener('click',()=>{resumePostOffice(state,b.dataset.postResume);save();navigate('#post');}));
 bind('[data-post-courier]',b=>setPostCourier(state,b.dataset.postCourier),'.post-courier-choice [aria-pressed="true"]');
 document.querySelectorAll('[data-post-composer]').forEach(el=>el.addEventListener('change',()=>{setPostComposer(state,el.dataset.postComposer,el.value);redraw(`#${el.id}`);}));
 bind('[data-post-add]',b=>{const v=current(state),kind=b.dataset.postAdd,c=v.composer;appendPostClause(state,kind==='there'?'there':`${kind}:${kind==='give'?c.recipient:c.place}`);},'.post-clauses');
 bind('[data-post-edit]',b=>editPostClause(state,Number(b.dataset.postIndex),b.dataset.postEdit),'.post-clauses');
 document.querySelector('#post-packing-input')?.addEventListener('input',event=>{setPostPackingInput(state,event.target.value);save();});
 document.querySelector('#post-packing-form')?.addEventListener('submit',event=>{event.preventDefault();submitPostPacking(state);redraw('#post-packing-feedback');});
 bind('[data-post-pack-together]',()=>packPostTogether(state),'#post-packing-feedback');
 bind('[data-post-step]',()=>stepPostRoute(state),'.post-flight-status');
 bind('[data-post-restart]',()=>restartPostRoute(state),'.post-flight-status');
 bind('[data-post-to-packing]',()=>{},'#post-packing-title');
 bind('[data-post-to-plan]',()=>{},'#post-route-title');
 bind('[data-post-to-flight]',()=>{},'#post-flight-title');
 bind('[data-post-edit-route]',()=>{},'#post-route-title');
 bind('[data-post-prediction]',b=>setPostPrediction(state,b.dataset.postPrediction==='clear'?null:b.dataset.postPrediction),'#post-prediction');
 bind('[data-post-reading]',b=>setPostReading(state,b.dataset.postReading),'#post-reading');
 bind('[data-post-help]',()=>setPostSupport(state,'helper'),'#post-example-title');
 bind('[data-post-help-step]',b=>stepPostHelp(state,b.dataset.postHelpStep==='reset'?'reset':Number(b.dataset.postHelpStep)),'#post-example-title');
 document.querySelectorAll('[data-post-next]').forEach(b=>b.addEventListener('click',()=>{const v=current(state),i=deliveries.findIndex(o=>o.id===v?.order?.id);startPostOffice(state,deliveries[(i+1)%deliveries.length].id);save();navigate('#post');focus('#post-order-title');}));
 document.querySelectorAll('.post-office-page [data-speak]').forEach(b=>b.addEventListener('click',()=>{setPostSupport(state,'audioRequested');save();}));
}
